import pandas as pd

def clean(df):
    df = df.copy()
    # normalize Category label variants (extra spaces)
    if 'Category' in df.columns:
        df['Category'] = df['Category'].astype(str).str.strip()
    # remove exact duplicate rows
    df = df.drop_duplicates()
    # make Price numeric for consistency
    if 'Price' in df.columns:
        df['Price'] = pd.to_numeric(df['Price'].astype(str).replace(r'[\$,]', '', regex=True), errors='coerce')
    # ensure Quantity is numeric
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    return df

def answer(df):
    dfc = clean(df)
    if 'Category' not in dfc.columns or 'Order_ID' not in dfc.columns:
        return {}
    # count distinct orders per category
    counts = dfc.groupby('Category')['Order_ID'].nunique()
    counts = counts.dropna()
    return {str(k): int(v) for k, v in counts.items()}
